mapper.select:
SELECT d.dict_code, d.dict_sort, d.dict_label, d.dict_value, d.dict_type, d.css_class, d.list_class, d.is_default, d.status, d.create_by, d.create_time, d.update_by, d.update_time, d.remark FROM sys_dict_data d
1 = 1
AND d.dict_type = #{dictData.dictType}
AND d.dict_label LIKE '%' || #{dictData.dictLabel} || '%'
AND d.status = #{dictData.status}
ORDER BY d.dict_sort
